Database Schema:
CREATE TABLE `author` (
  `aid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`aid`)
);

CREATE TABLE `conference` (
  `cid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  PRIMARY KEY (`cid`)
);

CREATE TABLE `domain` (
  `did` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_author` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_conference` (
  `cid` NUMBER REFERENCES `conference`(`cid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `journal` (
  `homepage` TEXT,
  `jid` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`jid`)
);

CREATE TABLE `domain_journal` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `jid` NUMBER REFERENCES `journal`(`jid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `keyword` (
  `keyword` TEXT,
  `kid` NUMBER,
  PRIMARY KEY (`kid`)
);

CREATE TABLE `domain_keyword` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `publication` (
  `abstract` TEXT,
  `cid` TEXT REFERENCES `conference`(`cid`),
  `citation_num` NUMBER,
  `jid` NUMBER REFERENCES `journal`(`jid`),
  `pid` NUMBER,
  `reference_num` NUMBER,
  `title` TEXT,
  `year` NUMBER,
  PRIMARY KEY (`pid`)
);

CREATE TABLE `domain_publication` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `organization` (
  `continent` TEXT,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`oid`)
);

CREATE TABLE `publication_keyword` (
  `pid` NUMBER REFERENCES `publication`(`pid`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`kid`)
);

CREATE TABLE `writes` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`aid`)
);

CREATE TABLE `cite` (
  `cited` NUMBER REFERENCES `publication`(`pid`),
  `citing` NUMBER REFERENCES `publication`(`pid`)
);

Question:
return me the journal that has the most number of papers containing keyword " Relational Database " .

Think through this step by step in <think> </think> tags. When you are finished thinking, close with </think> and IMMEDIATELY provide your final SQL query in <answer> \boxed{YOUR_SQL_QUERY} </answer> tags with no text in between.

To help you to solve this problem, an expert may have provided a partial solution. If provided, assume that this partial solution is correct and build on it to solve the problem.

Partial Solution: I start from publication-keyword associations and join the keyword table so I can identify papers tagged with the requested keyword: `FROM publication_keyword AS t4 JOIN keyword AS t1 ON t4.kid  =  t1.kid`.
I join each association to its publication and then to its journal, making the paper title and journal name available: `FROM publication_keyword AS t4 JOIN keyword AS t1 ON t4.kid  =  t1.kid JOIN publication AS t2 ON t2.pid  =  t4.pid JOIN journal AS t3 ON t2.jid  =  t3.jid`.
I restrict the joined rows to the keyword Relational Database: `FROM publication_keyword AS t4 JOIN keyword AS t1 ON t4.kid  =  t1.kid JOIN publication AS t2 ON t2.pid  =  t4.pid JOIN journal AS t3 ON t2.jid  =  t3.jid WHERE t1.keyword  =  "Relational Database"`.
I group by journal name and rank the journals by their number of distinct paper titles in descending order: `FROM publication_keyword AS t4 JOIN keyword AS t1 ON t4.kid  =  t1.kid JOIN publication AS t2 ON t2.pid  =  t4.pid JOIN journal AS t3 ON t2.jid  =  t3.jid WHERE t1.keyword  =  "Relational Database" GROUP BY t3.name ORDER BY COUNT ( DISTINCT t2.title ) DESC`.

